function next_smallest_palindrome(num) {
  let str = num.toString();
  let len = str.length;
  let half = len / 2;
  let left = str.slice(0, half);
  let right = str.slice(-half).split('').reverse().join('');

  // Check if the number is a palindrome
  if (left === right) {
    // If it is, increment the left part by 1 to get the next palindrome
    left = parseInt(left) + 1;
    // If the left part becomes a two-digit number, add a leading zero
    if (left < 10) {
      left = '0' + left;
    }
    // Construct the next palindrome by concatenating left, right, and the reversed left
    return parseInt(left + right);
  } else {
    // If it's not a palindrome, just return the number as it is
    return num;
  }
}

