function shell_sort(my_list){
    // Start with a large gap, then reduce the gap
    for (var gap = Math.floor(my_list.length / 2); gap > 0; gap = Math.floor(gap / 2)) {
        // Perform insertion sort with the current gap
        for (var i = gap; i < my_list.length; i++) {
            var temp = my_list[i];
            var j = i - gap;
            while (j >= 0 && my_list[j] > temp) {
                my_list[j + gap] = my_list[j];
                j -= gap;
            }
            my_list[j + gap] = temp;
        }
    }
    return my_list;
}

