function next_smallest_palindrome(num) {
    // Convert the number to a string to easily manipulate its digits
    let str = num.toString();
    let len = str.length;

    // Find the largest palindrome less than the given number
    for (let i = len - 2; i >= 0; i--) {
        let digit = str[i];
        // Check if the current digit can be increased to form a larger palindrome
        if (digit < '9') {
            let newStr = str.slice(0, i) + (digit + 1) + str.slice(i + 1);
            let newNum = parseInt(newStr, 10);
            if (newNum > num) {
                return newNum;
            }
        }
    }

    // If no palindrome can be found, return the next number that is a palindrome
    let nextNum = num + 1;
    while (!isPalindrome(nextNum)) {
        nextNum++;
    }
    return nextNum;
}

