function isPalindrome(num) {
    let str = num.toString();
    let len = str.length;
    for (let i = 0; i < len / 2; i++) {
        if (str[i] !== str[len - 1 - i]) {
            return false;
        }
    }
    return true;
}

function next_smallest_palindrome(num){
  let str = num.toString();
  let len = str.length;
  let half = Math.floor(len / 2);
  let left = str.substring(0, half);
  let right = str.substring(len - half);

  // Check if the number is a palindrome
  if (left === right.split('').reverse().join('')) {
    // If it is, find the next smallest palindrome by incrementing the right half
    for (let i = right.length - 1; i >= 0; i--) {
      if (right[i] < '9') {
        right[i]++;
        break;
      }
      right[i] = '0';
    }
    // If the right half is all '9's, increment the left half and adjust the right half
    if (right === '9'.repeat(len)) {
      left = String(Number(left) + 1);
      right = '0'.repeat(len - half);
    }
  } else {
    // If the number is not a palindrome, find the next smallest palindrome by incrementing the left half
    for (let i = left.length - 1; i >= 0; i--) {
      if (left[i] < '9') {
        left[i]++;
        break;
      }
      left[i] = '0';
    }
    // If the left half is all '9's, increment the right half and adjust the left half
    if (left === '9'.repeat(len)) {
      left = String(Number(left) + 1);
      right = '0'.repeat(len - half);
    }
  }

  // Combine the left and right halves to form the next smallest palindrome
  return Number(left + right);
}

