function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  const visited = new Set();
  const minPathLength = Infinity;
  const minPath = [];

  const dfs = (x, y, pathLength, path) => {
    if (pathLength === k) {
      if (path.length < minPathLength) {
        minPathLength = path.length;
        minPath = [...path];
      }
      return;
    }

    for (let i = 0; i < directions.length; i++) {
      const dx = directions[i][0];
      const dy = directions[i][1];
      const newX = x + dx;
      const newY = y + dy;

      if (newX >= 0 && newX < N && newY >= 0 && newY < N && !visited.has(`${newX},${newY}`)) {
        visited.add(`${newX},${newY}`);
        dfs(newX, newY, pathLength + 1, [...path, grid[newX][newY]]);
        visited.delete(`${newX},${newY}`);
      }
    }
  };

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      dfs(i, j, 1, [grid[i][j]]);
    }
  }

  return minPath;
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    const visited = new Array(N).fill(0).map(() => new Array(N).fill(false));
    const queue = [[grid[0][0], 0, 0]]; // [value, row, col]
    const path = new Array(k + 1).fill(null);
    const pathValues = new Array(k + 1).fill(null);
    const minPathValue = Infinity;
    const minPathIndex = -1;

    while (queue.length > 0) {
        const [value, row, col] = queue.shift();

        if (visited[row][col]) continue;
        visited[row][col] = true;

        if (row === N - 1 && col === N - 1) {
            if (pathValues[k] === null || pathValues[k] > value) {
                pathValues[k] = value;
                minPathValue = value;
                minPathIndex = k;
            }
        }

        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;

            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N) {
                queue.push([grid[newRow][newCol], newRow, newCol]);
            }
        }
    }

    return pathValues[minPathIndex];
}

