function max_sum(arr){
    let n = arr.length;
    let dp = new Array(n).fill(0);
    let dp_desc = new Array(n).fill(0);

    // Compute maximum sum of increasing subsequence
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < i; j++) {
            if (arr[j] < arr[i]) {
                dp[i] = Math.max(dp[i], dp[j] + arr[i]);
            }
        }
        dp[i] = Math.max(dp[i], arr[i]);
    }

    // Compute maximum sum of decreasing subsequence
    for (let i = n - 1; i >= 0; i--) {
        for (let j = n - 1; j > i; j--) {
            if (arr[j] < arr[i]) {
                dp_desc[i] = Math.max(dp_desc[i], dp_desc[j] + arr[i]);
            }
        }
        dp_desc[i] = Math.max(dp_desc[i], arr[i]);
    }

    // Find the maximum sum of bitonic subsequence
    let max_sum = 0;
    for (let i = 0; i < n; i++) {
        max_sum = Math.max(max_sum, dp[i] + dp_desc[i] - arr[i]);
    }

    return max_sum;
}

