function rearrange_bigger(n){
  // Convert number to string to manipulate digits
  let str = n.toString();
  let len = str.length;

  // Find the first digit from the right that is smaller than the digit immediately to its right
  for (let i = len - 2; i >= 0; i--) {
    if (str[i] < str[i + 1]) {
      // Find the smallest digit to the right of i that is greater than str[i]
      let j = len - 1;
      while (str[j] <= str[i]) {
        j--;
      }
      // Swap str[i] and str[j]
      [str[i], str[j]] = [str[j], str[i]];
      // Sort the digits to the right of i in ascending order
      str = str.slice(0, i + 1) + str.slice(i + 1).split('').sort().join('');
      // Return the rearranged number
      return parseInt(str);
    }
  }
  // If no bigger number can be formed, return -1
  return -1;
}

function rearrange_bigger(n){
    const digits = n.toString().split('');
    let isBigger = false;

    for (let i = digits.length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            isBigger = true;
            break;
        }
    }

    if (!isBigger) {
        return -1;
    }

    let j = i + 1;
    while (j < digits.length && digits[j] <= digits[i]) {
        j++;
    }

    [digits[i], digits[j]] = [digits[j], digits[i]];

    let left = i + 1, right = digits.length - 1;
    while (left < right) {
        [digits[left], digits[right]] = [digits[right], digits[left]];
        left++;
        right--;
    }

    return parseInt(digits.join(''));
}

