function toggle_middle_bits(n) {
  // Extract the first and last bits
  const firstBit = (n & 1) === 1;
  const lastBit = (n & (1 << (Math.floor(Math.log2(n)) - 1))) === 1;

  // Toggle the middle bits
  let middleBits = n;
  for (let i = 1; i < Math.floor(Math.log2(n)) - 1; i++) {
    middleBits ^= (1 << i);
  }

  // Combine the first and last bits with the toggled middle bits
  return firstBit ? (middleBits | 1) : (middleBits & ~1);
}

