function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    let minPath = [];
    let visited = new Set();
    let queue = [];

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            queue.push({
                path: [grid[i][j]],
                row: i,
                col: j,
                steps: 1
            });
        }
    }

    while (queue.length > 0) {
        const { path, row, col, steps } = queue.shift();

        if (steps === k) {
            minPath = path;
            break;
        }

        if (visited.has(`${row},${col}`)) continue;
        visited.add(`${row},${col}`);

        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;

            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N) {
                queue.push({
                    path: [...path, grid[newRow][newCol]],
                    row: newRow,
                    col: newCol,
                    steps: steps + 1
                });
            }
        }
    }

    return minPath;
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
    const visited = new Array(N).fill().map(() => new Array(N).fill(false));
    const distances = new Array(N).fill().map(() => new Array(N).fill(Number.MAX_SAFE_INTEGER));
    const path = [];

    const dfs = (x, y, steps) => {
        if (steps === k) {
            path.push(grid[x][y]);
            return;
        }

        for (const [dx, dy] of directions) {
            const nx = x + dx;
            const ny = y + dy;

            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny] && distances[nx][ny] + grid[nx][ny] < distances[x][y]) {
                visited[nx][ny] = true;
                distances[nx][ny] = distances[x][y] + grid[nx][ny];
                dfs(nx, ny, steps + 1);
                visited[nx][ny] = false;
            }
        }
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            if (!visited[i][j]) {
                visited[i][j] = true;
                distances[i][j] = grid[i][j];
                dfs(i, j, 1);
                visited[i][j] = false;
            }
        }
    }

    return path.sort((a, b) => a - b);
