    function sumOfDivisors(n) {
        let sum = 1; // 1 is always a divisor
        for (let i = 2; i <= Math.sqrt(n); i++) {
            if (n % i === 0) {
                sum += i;
                if (i !== n / i) {
                    sum += n / i;
                }
            }
        }
        return sum;
    }

    let sum = 0;
    for (let i = 2; i <= limit; i++) {
        let divSum = sumOfDivisors(i);
        if (divSum > i && sumOfDivisors(divSum) === i) {
            sum += i;
        }
    }
    return sum;
