    if (n === 0 && m === 0) return 1;
    if (n === 0 || m === 0) return 0;
    if (m > n) return 0;
    return (n - m) * eulerian_num(n - 1, m - 1) + (n - m) * eulerian_num(n - 1, m);
}

function eulerian_num(n, m) {
  if (m > n) {
    return 0;
  }
  if (m === 0) {
    return 1;
  }
  if (m === 1) {
    return n;
  }
  let result = 0;
  for (let i = 0; i <= m; i++) {
    result += (-1) ** i * (n - i) * eulerian_num(n - i, m - i);
  }
  return result;
}

