function pancake_sort(nums) {
  function flip(arr, i) {
    let start = 0;
    let end = i;
    while (start < end) {
      let temp = arr[start];
      arr[start] = arr[end];
      arr[end] = temp;
      start++;
      end--;
    }
  }

  function findMaxIndex(arr, n) {
    let maxIndex = 0;
    for (let i = 1; i < n; i++) {
      if (arr[i] > arr[maxIndex]) {
        maxIndex = i;
      }
    }
    return maxIndex;
  }

  for (let i = nums.length - 1; i > 0; i--) {
    let maxIndex = findMaxIndex(nums, i + 1);
    flip(nums, maxIndex);
    flip(nums, i);
  }

  return nums;
}

