  for(let i = 1; i < Input.length; i++){
    const currentSet = new Set(Input[i]);

    // Find common elements between the current array and the unique elements
    const commonElements = Array.from(uniqueElements).filter(element => currentSet.has(element));

    // If no common elements are found, return null
    if(commonElements.length === 0){
      return null;
    }

    // Update the unique elements with the common elements
    uniqueElements = new Set(commonElements);
  }

  // Return the first common element found
  return Array.from(uniqueElements)[0];
}

