function maxAverageOfPath(cost) {
    const N = cost.length;
    const dp = Array.from({ length: N }, () => Array(N).fill(0));

    // Fill the dp array
    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            if (i === 0 && j === 0) {
                dp[i][j] = cost[i][j];
            } else {
                const up = i > 0 ? dp[i - 1][j] : 0;
                const left = j > 0 ? dp[i][j - 1] : 0;
                dp[i][j] = cost[i][j] + Math.max(up, left);
            }
        }
    }

    // Calculate the maximum average path
    let maxAverage = -Infinity;
    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            const totalCost = dp[i][j];
            const pathLength = i + j + 1;
            const average = totalCost / pathLength;
            maxAverage = Math.max(maxAverage, average);
        }
    }

    return maxAverage;
}

