function re_arrange_array(arr, n) {
  let negative = [];
  let positive = [];

  // Separate positive and negative numbers
  for (let i = 0; i < n; i++) {
    if (arr[i] < 0) {
      negative.push(arr[i]);
    } else {
      positive.push(arr[i]);
    }
  }

  // Merge negative and positive numbers while preserving the relative order
  let result = [];
  for (let i = 0; i < n; i++) {
    if (i < negative.length) {
      result.push(negative[i]);
    }
    if (i < positive.length) {
      result.push(positive[i]);
    }
  }

  return result;
}

