function max_sum_increasing_subseq(a, n, index, k) {
    if (index === n || k >= n) {
        return 0;
    }

    let includeK = a[k];
    let excludeK = max_sum_increasing_subseq(a, n, index + 1, k);

    return Math.max(includeK + max_sum_increasing_subseq(a, n, index + 1, k + 1), excludeK);
}

function max_sum_increasing_subseq(a, n, index, k) {
    let dp = new Array(n + 1).fill(0);
    let max_sum = 0;

    for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
            if (a[i] < a[j] && i < index && j > k) {
                dp[j] = Math.max(dp[j], dp[i] + a[j]);
            }
        }
        max_sum = Math.max(max_sum, dp[i]);
    }

    return max_sum;
}

function max_Product(arr){
    if(arr.length < 2){
        throw new Error("Array must contain at least two elements.");
    }

    let max1 = arr[0];
    let max2 = arr[1];
    let min1 = arr[0];
    let min2 = arr[1];

    for(let i = 2; i < arr.length; i++){
        if(arr[i] > max1){
            max2 = max1;
            max1 = arr[i];
        } else if(arr[i] > max2){
            max2 = arr[i];
        }

        if(arr[i] < min1){
            min2 = min1;
            min1 = arr[i];
        } else if(arr[i] < min2){
            min2 = arr[i];
        }
    }

    return Math.max(max1 * max2, min1 * min2);
}

function max_Product(arr){
