    let maxProduct = arr[0] * arr[1];
    let minProduct = arr[0] * arr[1];

    for(let i = 2; i < arr.length; i++){
        if(arr[i] > maxProduct){
            maxProduct = arr[i] * maxProduct;
        }
        if(arr[i] < minProduct){
            minProduct = arr[i] * minProduct;
        }
    }

    return Math.max(maxProduct, minProduct);
}

