function find_length(string){
  let maxDiff = 0;
  let currentDiff = 0;
  let countZeroes = 0;
  let countOnes = 0;

  for (let i = 0; i < string.length; i++) {
    if (string[i] === '0') {
      countZeroes++;
    } else {
      countOnes++;
    }

    currentDiff = countZeroes - countOnes;

    if (currentDiff > maxDiff) {
      maxDiff = currentDiff;
    }
  }

  return maxDiff;
}

function find_length(string){
  let maxDifference = 0;
  let currentDifference = 0;
  let zeroCount = 0;
  let oneCount = 0;

  for (let i = 0; i < string.length; i++) {
    if (string[i] === '0') {
      zeroCount++;
    } else {
      oneCount++;
    }

    currentDifference = Math.abs(zeroCount - oneCount);
    maxDifference = Math.max(maxDifference, currentDifference);
  }

  return maxDifference;
}

