function find_combinations(test_list){
  const result = [];
  const helper = (index, currentSum, currentCombination) => {
    if (index === test_list.length) {
      if (currentSum === 0) {
        result.push(currentCombination.slice());
      }
      return;
    }
    helper(index + 1, currentSum, currentCombination);
    currentCombination.push(test_list[index]);
    helper(index + 1, currentSum + test_list[index], currentCombination);
    currentCombination.pop();
  };
  helper(0, 0, []);
  return result;
}

