function group_tuples(Input){
  if (Input.length === 0) return null; // Return null if the input array is empty

  // Find the minimum length of the arrays in the input array
  let minLength = Math.min(...Input.map(arr => arr.length));

  // Check if all arrays have the same length
  if (minLength !== Input.reduce((acc, arr) => acc && arr.length === minLength, true)) {
    throw new Error("All arrays must have the same length");
  }

  // Find the common first element in all arrays
  let commonFirst = Input[0][0];
  for (let i = 1; i < minLength; i++) {
    commonFirst = Input[0][i] === Input[i][i] ? commonFirst : null;
    if (commonFirst === null) break;
  }

  return commonFirst;
}

