        neighbors.push([newRow, newCol]);
      }
    }

    let minPath = Infinity;
    for (const [newRow, newCol] of neighbors) {
      const newPath = [...path, grid[newRow][newCol]];
      const newSteps = steps + 1;
      const currentPath = dfs(newRow, newCol, newPath, newSteps);
      if (currentPath && currentPath.length < minPath) {
        minPath = currentPath;
      }
    }

    return minPath;
  }

  let minPath = Infinity;
  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      const path = [grid[i][j]];
      const steps = 1;
      const currentPath = dfs(i, j, path, steps);
      if (currentPath && currentPath.length < minPath) {
        minPath = currentPath;
      }
    }
  }

