function minPath(grid, k){
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]];
    const visited = new Array(N).fill().map(() => new Array(N).fill(false));
    const path = new Array(k + 1).fill(0);
    const minPath = [];

    const dfs = (row, col, steps) => {
        if (steps === k) {
            minPath.push(...path);
            return;
        }

        for (const [dx, dy] of directions) {
            const newRow = row + dx;
            const newCol = col + dy;

            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
                visited[newRow][newCol] = true;
                path[steps] = grid[newRow][newCol];
                dfs(newRow, newCol, steps + 1);
                path[steps] = 0;
                visited[newRow][newCol] = false;
            }
        }
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            visited[i][j] = true;
            path[0] = grid[i][j];
            dfs(i, j, 1);
            path[0] = 0;
            visited[i][j] = false;
        }
    }

    return minPath.sort((a, b) => a - b);
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]]; // Right, Down, Left, Up
    const visited = Array.from({ length: N }, () => Array(N).fill(false));

    function dfs(row, col, path, steps) {
        if (steps === k) {
            return path;
        }

        visited[row][col] = true;
        const neighbors = directions.map(([dr, dc]) => [row + dr, col + dc]);

        for (const [nr, nc] of neighbors) {
            if (nr >= 0 && nr < N && nc >= 0 && nc < N && !visited[nr][nc]) {
                const newPath = [...path, grid[nr][nc]];
                const result = dfs(nr, nc, newPath, steps + 1);
                if (result) {
                    return result;
                }
            }
        }

        visited[row][col] = false;
        return null;
    }

    let minPath = null;
    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            const result = dfs(i, j, [grid[i][j]], 1);
            if (result && (minPath === null || result < minPath)) {
                minPath = result;
            }
        }
    }

    return minPath;
}

