function isNewmanShanksWilliamsPrime(num) {
  if (num < 2) return false;

  const sqrtNum = Math.sqrt(num);
  for (let i = 2; i <= sqrtNum; i++) {
    if (num % i === 0) return false;
  }

  const a = 2;
  let b = 1;
  let c = 1;

  while (true) {
    const nextC = 3 * c * c + 4 * a * b;
    const nextB = 2 * a * b + c;
    const nextA = a;

    if (nextC > num) break;

    if (nextC === num) return true;

    a = nextA;
    b = nextB;
    c = nextC;
  }

  return false;
}

