function max_product(arr){
  if(arr.length === 0) return 0;

  let dp = Array(arr.length).fill(1);
  let maxProduct = arr[0];

  for(let i = 1; i < arr.length; i++){
    for(let j = 0; j < i; j++){
      if(arr[i] > arr[j] && dp[i] < dp[j] * arr[i]){
        dp[i] = dp[j] * arr[i];
      }
    }
    maxProduct = Math.max(maxProduct, dp[i]);
  }

  return maxProduct;
}

