function minPath(grid, k) {
    const N = grid.length;
    const visited = Array.from({ length: N }, () => Array(N).fill(false));
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const minPathValues = [];

    function dfs(row, col, path, steps) {
        if (steps === k) {
            minPathValues.push(path.slice());
            return;
        }

        for (let d of directions) {
            const newRow = row + d[0];
            const newCol = col + d[1];

            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N && !visited[newRow][newCol]) {
                visited[newRow][newCol] = true;
                dfs(newRow, newCol, path.concat(grid[newRow][newCol]), steps + 1);
                visited[newRow][newCol] = false;
            }
        }
    }

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, [grid[i][j]], 1);
        }
    }

    minPathValues.sort((a, b) => {
        for (let i = 0; i < Math.min(a.length, b.length); i++) {
            if (a[i] < b[i]) return -1;
            if (a[i] > b[i]) return 1;
        }
        return a.length - b.length;
    });

    return minPathValues[0];
}

function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]]; // Right, Down, Up, Left

    const visited = new Set();
    const queue = [[0, 0, 0]]; // [row, col, steps]

    while (queue.length > 0) {
        const [row, col, steps] = queue.shift();

        if (steps === k) {
            return grid[row][col];
        }

        if (visited.has(`${row},${col}`)) continue;

        visited.add(`${row},${col}`);

        for (const [dr, dc] of directions) {
            const newRow = row + dr;
            const newCol = col + dc;

            if (newRow >= 0 && newRow < N && newCol >= 0 && newCol < N) {
                queue.push([newRow, newCol, steps + 1]);
            }
        }
    }

    return null; // In case no path is found
}

