function toggle_middle_bits(n) {
    // Calculate the number of bits in the number
    const numBits = Math.floor(Math.log2(n)) + 1;

    // Create a mask to toggle the middle bits
    const mask = ((1 << (numBits - 2)) - 1) ^ (1 << 0) ^ (1 << (numBits - 1));

    // Toggle the middle bits
    return n ^ mask;
}

function toggle_middle_bits(n) {
    // Remove the first and last bits
    let midBits = n >> 1;
    midBits &= ~(1 << 0) | ~(1 << 31); // Set the first and last bits to 0
    // Toggle the middle bits
    midBits ^= 0xAAAAAAAA; // Toggle all bits except the first and last
    return midBits << 1; // Re-add the first bit
}

