function bell_number(n){
    if (n === 0) return 1;
    let bell = [1];
    for (let i = 1; i <= n; i++) {
        let nextBell = 0;
        for (let j = 0; j < i; j++) {
            nextBell += bell[j] * bell[i - j - 1];
        }
        bell.push(nextBell);
    }
    return bell[n];
}

