function encode(message) {
  const vowels = 'aeiouAEIOU';
  const nextVowel = (vowel) => {
    const index = vowels.indexOf(vowel);
    const newIndex = (index + 2) % vowels.length;
    return vowels[newIndex];
  };

  return message.split('').map(char => {
    if (vowels.includes(char)) {
      return nextVowel(char);
    }
    return char === char.toUpperCase() ? char.toLowerCase() : char.toUpperCase();
  }).join('');
}

function encode(message) {
  const vowels = 'aeiouAEIOU';
  const shift = (char) => {
    const code = char.charCodeAt(0);
    if (code >= 65 && code <= 90) {
      return String.fromCharCode(((code - 65 + shift) % 26) + 65);
    } else if (code >= 97 && code <= 122) {
      return String.fromCharCode(((code - 97 + shift) % 26) + 97);
    }
    return char;
  };

  return message.split('').map(char => {
    if (vowels.includes(char)) {
      const index = vowels.indexOf(char);
      const nextVowelIndex = (index + 2) % vowels.length;
      return shift(vowels[nextVowelIndex]);
    }
    return shift(char);
  }).join('');
}

