  if (n === 2) return b;

  // Generate the sequence up to the nth number
  while (count < n) {
    // Calculate the next number in the sequence
    let next = a + b;
    // Update the current numbers for the next iteration
    a = b;
    b = next;
    // Increment the count
    count++;
  }

