  Input.forEach(subArray => subArray.sort((a, b) => a - b));

  // Find the common first element
  let commonFirstElement = null;
  for (let i = 0; i < Input[0].length; i++) {
    let firstElement = Input[0][i];
    let isCommon = true;
    for (let j = 1; j < Input.length; j++) {
      if (Input[j][i] !== firstElement) {
        isCommon = false;
        break;
      }
    }
    if (isCommon) {
      commonFirstElement = firstElement;
      break;
    }
  }

  return commonFirstElement;
}

