function minPath(grid, k) {
  const N = grid.length;
  const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
  const visited = new Array(N).fill().map(() => new Array(N).fill(false));
  const path = [];
  const minPathLength = k;

  function dfs(x, y, steps) {
    if (steps === minPathLength) {
      path.push(...grid[x][y].map(val => val));
      return;
    }

    for (const [dx, dy] of directions) {
      const newX = x + dx;
      const newY = y + dy;

      if (newX >= 0 && newX < N && newY >= 0 && newY < N && !visited[newX][newY]) {
        visited[newX][newY] = true;
        dfs(newX, newY, steps + 1);
        visited[newX][newY] = false;
      }
    }
  }

  for (let i = 0; i < N; i++) {
    for (let j = 0; j < N; j++) {
      visited[i][j] = true;
      dfs(i, j, 1);
      visited[i][j] = false;
    }
  }

  path.sort((a, b) => a - b);
  return path;
}

function minPath(grid, k){
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [0, -1], [-1, 0]]; // Right, Down, Left, Up

    function dfs(x, y, path, steps){
        if(steps === k){
            return path;
        }
        const visited = new Set();
        const queue = [[x, y, path, steps]];

        while(queue.length){
            const [i, j, currentPath, currentSteps] = queue.shift();

            if(visited.has(`${i},${j}`)){
                continue;
            }
            visited.add(`${i},${j}`);

            for(let [dx, dy] of directions){
                const newX = i + dx;
                const newY = j + dy;

                if(newX >= 0 && newX < N && newY >= 0 && newY < N){
                    const value = grid[newX][newY];
                    const newPath = [...currentPath, value];

                    if(newPath.length === k){
                        return newPath;
                    }

                    queue.push([newX, newY, newPath, currentSteps + 1]);
                }
            }
        }

        return null;
    }

    let minPathValue = Infinity;
    let minPath = [];

    for(let i = 0; i < N; i++){
        for(let j = 0; j < N; j++){
            const path = dfs(i, j, [grid[i][j]], 1);
            if(path && path.length === k && path.join(',') < minPathValue){
                minPathValue = path.join(',');
                minPath = path;
            }
        }
    }

    return minPath;
}

