    for (let i = index + 1; i < n; i++) {
        if (a[i] > a[index]) {
            maxSum = Math.max(maxSum, max_sum_increasing_subseq(a, n, i, k) + a[i]);
        }
    }

    if (k > index) {
        let maxSumIncludingK = max_sum_increasing_subseq(a, n, index + 1, k) + a[k];
        maxSum = Math.max(maxSum, maxSumIncludingK);
    }

