function max_sum_increasing_subseq(a, n, index, k) {
    // Initialize a 2D array to store the maximum sum of increasing subsequence up to each index and including a given kth element
    const dp = Array.from({ length: n }, () => Array.from({ length: k + 1 }, () => 0));

    // Fill the dp array
    for (let i = 0; i < n; i++) {
        for (let j = 0; j <= k; j++) {
            if (i === 0) {
                dp[i][j] = a[i];
            } else if (i === 1) {
                dp[i][j] = Math.max(dp[i - 1][j], a[i]);
            } else {
                dp[i][j] = Math.max(dp[i - 1][j], dp[i - 1][j - 1] + a[i]);
            }
        }
    }

    // The maximum sum of increasing subsequence including the kth element is the maximum value in the dp array
    return dp[n - 1][k];
}

function max_sum_increasing_subseq(a, n, index, k) {
    // Initialize a 2D array to store the maximum sum of increasing subsequence up to each index and including a given kth element
    const dp = Array.from({ length: n }, () => Array.from({ length: n + 1 }, () => 0));

    // Iterate through each element in the array
    for (let i = 0; i < n; i++) {
        for (let j = i; j <= n; j++) {
            // Check if the current element is greater than the previous element
            if (a[i] < a[j]) {
                // Update the maximum sum of increasing subsequence up to the current index and including the given kth element
                dp[i][j] = Math.max(dp[i][j], dp[i][i] + dp[i + 1][j]);
            }
        }
    }

    // Return the maximum sum of increasing subsequence up to the given index and including the given kth element
    return dp[index][k];
}

