function rearrange_bigger(n) {
    let str = n.toString().split('');
    let len = str.length;

    // Find the first digit from the right that is smaller than the digit next to it
    let i = len - 2;
    while (i >= 0 && str[i] >= str[i + 1]) {
        i--;
    }

    if (i === -1) {
        return -1; // The number is the largest possible permutation
    }

    // Find the smallest digit to the right of i that is greater than str[i]
    let j = len - 1;
    while (j >= 0 && str[j] <= str[i]) {
        j--;
    }

    // Swap the digits at positions i and j
    [str[i], str[j]] = [str[j], str[i]];

    // Sort the digits to the right of i in ascending order
    str.splice(i + 1, len - i - 1).sort((a, b) => a - b);

    // Combine the digits back into a number
    return parseInt(str.join(''));
}

function rearrange_bigger(n) {
  // Convert the number to an array of its digits
  const digits = Array.from(String(n), Number);

  // Find the index of the first digit that is smaller than the digit immediately after it
  let i = digits.length - 2;
  while (i >= 0 && digits[i] >= digits[i + 1]) {
    i--;
  }

  // If no such digit is found, the number is the largest possible permutation
  if (i === -1) return -1;

  // Find the smallest digit to the right of i that is larger than digits[i]
  let j = digits.length - 1;
  while (j > i && digits[j] <= digits[i]) {
    j--;
  }

  // Swap digits[i] and digits[j]
  [digits[i], digits[j]] = [digits[j], digits[i]];

  // Reverse the digits to the right of i
  digits.splice(i + 1);
  digits.reverse();

  // Convert the array back to a number
  return parseInt(digits.join(''));
}

