function minPath(grid, k) {
    const N = grid.length;
    const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
    const visited = new Set();
    const minPath = [];
    const pathLength = 0;
    const directionsVisited = new Set();

    const isSafe = (x, y) => {
        return x >= 0 && x < N && y >= 0 && y < N && !visited.has(`${x},${y}`);
    };

    const dfs = (x, y, path, pathLength) => {
        if (pathLength === k) {
            if (minPath.length === 0 || path < minPath) {
                minPath = [...path];
            }
            return;
        }

        visited.add(`${x},${y}`);

        for (const [dx, dy] of directions) {
            const newX = x + dx;
            const newY = y + dy;
            if (isSafe(newX, newY)) {
                dfs(newX, newY, [...path, grid[newX][newY]], pathLength + 1);
            }
        }

        visited.delete(`${x},${y}`);
    };

    for (let i = 0; i < N; i++) {
        for (let j = 0; j < N; j++) {
            dfs(i, j, [grid[i][j]], 1);
        }
    }

    return minPath;
}

function minPath(grid, k) {
  const rows = grid.length;
  const cols = grid[0].length;
  const directions = [[0, 1], [1, 0], [-1, 0], [0, -1]];
  const visited = new Set();
  const minPath = [];

  function dfs(row, col, steps, path) {
    if (steps === k) {
      minPath.push([...path]);
      return;
    }

    if (row < 0 || row >= rows || col < 0 || col >= cols || visited.has(`${row},${col}`)) {
      return;
    }

    visited.add(`${row},${col}`);
    path.push(grid[row][col]);

    for (const [dr, dc] of directions) {
      dfs(row + dr, col + dc, steps + 1, path);
    }

    path.pop();
    visited.delete(`${row},${col}`);
  }

  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      dfs(i, j, 0, []);
    }
  }

  minPath.sort((a, b) => a.toString() < b.toString() ? -1 : 1);

  return minPath[0];
}

