function occurance_substring(text, pattern) {
  let occurrences = [];
  let index = 0;

  while ((index = text.indexOf(pattern, index)) !== -1) {
    occurrences.push({ position: index, count: occurrences.length + 1 });
    index++; // Move to the next character to avoid overlapping matches
  }

  return occurrences;
}

